import { state, user, userAvatar, svg, esc, sessionMedia } from './core.js';
import { workspaceSidebar } from './navigation.js';

const topicColors = ['tone-rose', 'tone-lav', 'tone-sage', 'tone-blue'];
const namespaceSlugs = new Map([['Women’s Health', 'womenshealth'], ['PCOS & Hormonal Health', 'pcos'], ['Mental Wellness', 'mentalwellness'], ['Reproductive Health', 'reproductivehealth'], ['Health Research', 'healthresearch']]);
const samplePostAssets=Object.fromEntries(Object.entries(import.meta.glob('/assets/SamplePOSTS/*.{jpg,jpeg,png,webp,mp4}',{eager:true,query:'?url',import:'default'})).map(([path,url])=>[path.split('/').pop(),url]));
const communityBannerAssets=Object.fromEntries(Object.entries(import.meta.glob('/assets/community and profile banners/*.{jpg,jpeg,png,webp}',{eager:true,query:'?url',import:'default'})).map(([path,url])=>[path.split('/').pop(),url]));
const profilePictureAssets=Object.fromEntries(Object.entries(import.meta.glob('/assets/PFPs/*.{jpg,jpeg,png,webp}',{eager:true,query:'?url',import:'default'})).map(([path,url])=>[path.split('/').pop(),url]));
export const sampleMediaUrl=filename=>samplePostAssets[filename]||'';
export const sampleProfilePicture=filename=>profilePictureAssets[filename]||'';
export const samplePosterUrl=filename=>samplePostAssets[filename]||profilePictureAssets[filename]||communityBannerAssets[filename]||'';
const communityBanner=filename=>communityBannerAssets[filename]||'';
let reelSoundEnabled=false;
export const toggleReelSound=()=>{reelSoundEnabled=!reelSoundEnabled;return reelSoundEnabled;};
const communityBanners={
  'Women’s Health':communityBanner('2e342832776ffc0eab47b6118a8d794a.jpg'),
  'PCOS & Hormonal Health':communityBanner('25c54de70b796e333a7f59a9da430508.jpg'),
  'Mental Wellness':communityBanner('3542df9548dcee6f289573457e71226f.jpg'),
  'Reproductive Health':communityBanner('f2d1c916b25326ae12cc8dec44f9015a.jpg'),
  'Health Research':communityBanner('678cabb80896cde1ce765b84e59f9ecb.jpg')
};
const profileCovers={
  QuietRiver:communityBanners['Women’s Health'],SoftMorning:communityBanners['PCOS & Hormonal Health'],
  KindOak:communityBanners['Mental Wellness'],MapleSky:communityBanners['Reproductive Health'],
  MiraSol:communityBanners['Health Research'],quietriver:communityBanners['Women’s Health'],
  softmorning:communityBanners['PCOS & Hormonal Health'],kindoak:communityBanners['Mental Wellness'],
  maplesky:communityBanners['Reproductive Health'],mirasol:communityBanners['Health Research']
};
export const sampleProfileCover=name=>profileCovers[String(name||'')]||communityBanners['Women’s Health'];
const curatedSampleExploreItems = [
  { id:'media-mindful', kind:'image', media:'c40eb26002f0228fd17f8d4aa6eb6753.jpg', alt:'Illustration of a woman meditating beneath a sun and moon', title:'A little room to reset', caption:'A quiet visual moment for a slower day.', category:'Mental Wellness', format:'Illustration' },
  { id:'media-movement', kind:'image', media:'cc6236da26bcdedbc33249bcdf6df709.jpg', alt:'Women pictured in a women’s health campaign poster', title:'Women’s health, in focus', caption:'A campaign visual from the sample collection.', category:'Women’s Health', format:'Visual story' },
  { id:'media-care', kind:'video', media:'paalavwomenshospital_pindown.io_1793762010.mp4', poster:'a46aebb46857aa89985df74610473784.jpg', alt:'Sample video from the local media collection', title:'A short care-space preview', caption:'A sample clip. The source and credentials are not verified.', category:'Women’s Health', format:'Video' },
  { id:'media-portrait', kind:'image', media:'03eff9cb59bc46498ad6eb5220ef17d3.jpg', alt:'Woman sitting in a calm, plant-filled room', title:'Care for every stage of life', caption:'An editorial image from the sample collection.', category:'Women’s Health', format:'Editorial' },
  { id:'media-art', kind:'image', media:'5d0010bb12258267818263d3f6496a94.jpg', alt:'Illustration of a diverse group of women', title:'Many stories, one community', caption:'An illustration celebrating the many ways people show up for one another.', category:'For You', format:'Illustration' },
  { id:'media-hydration', kind:'image', media:'2ff3ce45f82f02daefeb42703003d924.jpg', alt:'Woman taking a drink of water after exercise', title:'A pause between things', caption:'A lifestyle image from the sample collection; no health claim is implied.', category:'Fitness', format:'Lifestyle' },
  { id:'media-period', kind:'image', media:'97db363828293e6f2613bb5f49c1e6a7.jpg', alt:'Illustrated period comfort campaign', title:'A visual about period comfort', caption:'This sample graphic has no source details attached.', category:'Women’s Health', format:'Infographic' },
  { id:'media-wellness', kind:'image', media:'04dbe594bf1953c634c0092810c5e3ba.jpg', alt:'Editorial image of a woman in a calm interior', title:'Wellness, on your own terms', caption:'A campaign-style image from the sample collection.', category:'For You', format:'Editorial' },
  { id:'media-yoga-video', kind:'video', media:'tinagulian_pindown.io_1793761972.mp4', poster:'c40eb26002f0228fd17f8d4aa6eb6753.jpg', alt:'Sample movement video from the local media collection', title:'Movement, at your pace', caption:'A sample clip. The source and any advice in it are unverified.', category:'Fitness', format:'Video' },
  { id:'media-research', kind:'image', media:'a46aebb46857aa89985df74610473784.jpg', alt:'Illustration about women’s health and wellbeing', title:'An illustrated view of women’s health', caption:'An educational-style graphic from the sample collection; its claims are not verified.', category:'Women’s Health', format:'Unverified graphic' },
  { id:'media-care-video', kind:'video', media:'philomoha77_pindown.io_1793761845.mp4', poster:'03eff9cb59bc46498ad6eb5220ef17d3.jpg', alt:'Sample wellness video from the local media collection', title:'A moment in motion', caption:'Sample video · creator and source not verified.', category:'For You', format:'Video' },
  { id:'media-hospital-video', kind:'video', media:'madeinprosto_pindown.io_1793761828.mp4', poster:'0583432b268ec4640058823a7b8e8218.jpg', alt:'Sample women’s health video from the local media collection', title:'A community visual story', caption:'Sample video · creator and source not verified.', category:'Women’s Health', format:'Video' }
];
const featuredVideoFiles=new Set(curatedSampleExploreItems.filter(item=>item.kind==='video').map(item=>item.media));
const usedExploreImages=new Set(curatedSampleExploreItems.flatMap(item=>[item.kind==='image'?item.media:'',item.poster||''].filter(Boolean)));
const extraPosterFiles=[...new Set([...Object.keys(samplePostAssets),...Object.keys(profilePictureAssets),...Object.keys(communityBannerAssets)])].filter(filename=>/\.(jpg|jpeg|png|webp)$/i.test(filename)&&!usedExploreImages.has(filename));
const additionalVideoItems=Object.keys(samplePostAssets).filter(filename=>/\.mp4$/i.test(filename)&&!featuredVideoFiles.has(filename)).map((media,index)=>{
  const stem=media.replace(/\.mp4$/i,'').replace(/_pindown\.io_\d+$/i,'').replace(/_720w$/i,'').replace(/[_-]+/g,' ').trim();
  const category=/nutri|food/i.test(stem)?'Nutrition':/fit|yoga|movement|naali/i.test(stem)?'Fitness':/women|hospital|health|medical|myupchar/i.test(stem)?'Women’s Health':'For You';
  const title=/^[a-f\d\s]{16,}$/i.test(stem)?({Nutrition:'Everyday nutrition ideas',Fitness:'Movement, at your pace','Women’s Health':'A moment of care','For You':'A story in motion'}[category]):`${stem.replace(/\b\w/g,char=>char.toUpperCase())} · Sample video`;
  const poster=extraPosterFiles.length?extraPosterFiles[index%extraPosterFiles.length]:'';
  return {id:`media-extra-${media.replace(/[^a-z0-9]+/gi,'-').replace(/-+$/,'').toLowerCase()}`,kind:'video',media,poster,alt:`Sample video from ${stem}`,title,caption:'Sample video · creator and source not verified.',category,format:'Video'};
});
export const sampleExploreItems=[...curatedSampleExploreItems,...additionalVideoItems];
export const sampleStories = [
  { id:'sample-story-care', author:'MiraSol', initials:'MS', media:sampleMediaUrl('paalavwomenshospital_pindown.io_1793762010.mp4'), poster:sampleMediaUrl('a46aebb46857aa89985df74610473784.jpg'), caption:'A conversation about everyday care.', time:'19h' },
  { id:'sample-story-care-2', author:'MiraSol', initials:'MS', media:sampleMediaUrl('madeinprosto_pindown.io_1793761828.mp4'), poster:sampleMediaUrl('0583432b268ec4640058823a7b8e8218.jpg'), caption:'A second perspective from today.', time:'18h' },
  { id:'sample-story-movement', author:'KindOak', initials:'KO', media:sampleMediaUrl('tinagulian_pindown.io_1793761972.mp4'), poster:sampleMediaUrl('c40eb26002f0228fd17f8d4aa6eb6753.jpg'), caption:'Finding a pace that feels right.', time:'8h' },
  { id:'sample-story-wellness', author:'SoftMorning', initials:'SM', media:sampleMediaUrl('philomoha77_pindown.io_1793761845.mp4'), poster:sampleMediaUrl('03eff9cb59bc46498ad6eb5220ef17d3.jpg'), caption:'A small moment from today.', time:'5h' }
];
const exploreCategories = ['For You', 'Women’s Health', 'PCOS', 'Mental Wellness', 'Nutrition', 'Fitness', 'Skincare', 'Research', 'Doctors', 'Communities'];
const communityData = () => {
  const saved = state.communityCatalog || [];
  const names = [...new Set([...saved.map(item => item.name), ...state.posts.map(post => post.community), 'Women’s Health', 'PCOS & Hormonal Health', 'Mental Wellness', 'Reproductive Health', 'Health Research'])];
  return names.map((name,index)=>{
    const stored=saved.find(item=>item.name===name);
    return {
      ...(stored||{}),name,
      slug:stored?.slug||namespaceSlugs.get(name)||name.toLowerCase().replace(/[’']/g, '').normalize('NFKD').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''),
      description:stored?.description||'A thoughtful space for shared experience, questions and support.',
      members:stored?.members??null,color:stored?.color||topicColors[index%topicColors.length],
      cover:stored?.bannerImage||stored?.cover||communityBanners[name]||communityBanners['Women’s Health']
    };
  });
};
const activeSection = () => state.communitySection || 'home';
const memberLabel = item => item.members == null ? 'Member count unavailable' : `${item.members.toLocaleString()} members`;
const postCount = post => post.comments?.length || 0;
const sampleVisuals = {
  p1: ['Your questions deserve the time they need.', 'rose'],
  p2: ['Start with what matters most today.', 'sage'],
  p3: ['Small notes can make space for patterns.', 'blue']
};

function samplePostArtwork(post) {
  const [quote, tone] = post.visualQuote ? [post.visualQuote, post.visualTone || 'rose'] : sampleVisuals[post.id] || [];
  if (!quote) return '';
  return `<div class="vc-post-art tone-${esc(tone)}" role="img" aria-label="Illustrative sample post: ${esc(quote)}"><span class="vc-art-orbit orbit-one"></span><span class="vc-art-orbit orbit-two"></span><span class="vc-art-symbol">${svg('spark', 24)}</span><span class="vc-art-caption">SAMPLE COMMUNITY NOTE</span><strong>${esc(quote)}</strong><span class="vc-art-foot">VERICOVE · COMMUNITY</span></div>`;
}

function postCommentsMarkup(post){
  const comments=(post.comments||[]).map((comment,index)=>{comment.id||=`${post.id}-comment-${index}`;return comment;});
  const renderComment=(comment,depth=0)=>`<article class="thread-comment" style="--reply-depth:${Math.min(depth,4)}"><span class="thread-avatar">${userAvatar({name:comment.author})}</span><div class="thread-comment-copy"><div class="thread-comment-head"><strong>${esc(comment.author)}</strong><time>${esc(comment.time||'Recently')}</time></div><p>${esc(comment.text)}</p><div class="thread-comment-actions"><button type="button" class="reply-link" data-action="reply-to" data-id="${esc(post.id)}" data-comment-id="${esc(comment.id||'')}" data-author="${esc(comment.author)}">Reply</button><button type="button" class="thread-like ${(state.commentLikes||[]).includes(comment.id)?'is-liked':''}" data-action="like-comment" data-id="${esc(post.id)}" data-comment-id="${esc(comment.id||'')}" aria-label="Like comment">${svg('heart',15)}</button></div>${comments.filter(child=>child.parentId===comment.id).map(child=>renderComment(child,depth+1)).join('')}</div></article>`;
  const roots=comments.filter(comment=>!comment.parentId||!comments.some(item=>item.id===comment.parentId));
  return `<div class="vc-post-comments-thread-list">${roots.map(comment=>renderComment(comment)).join('')||'<p class="empty-thread">Be the first to start the conversation.</p>'}</div><div class="reply-target" id="reply-target" hidden><span></span><button type="button" data-action="cancel-reply" aria-label="Cancel reply">×</button></div><form class="comment-form" data-post-id="${esc(post.id)}"><input type="hidden" name="parentId" value=""><label class="sr-only" for="reply-content">Write a reply</label><textarea id="reply-content" name="comment" rows="2" maxlength="600" placeholder="Add a thoughtful reply…" required></textarea><button class="btn primary" type="submit">Reply</button></form>`;
}
function postCommentsPanel(post){return `<section class="vc-post-comments-panel" aria-label="Comments on ${esc(post.title||'post')}"><header><strong>Comments <span>${postCount(post)}</span></strong><button type="button" data-action="toggle-comments" data-id="${esc(post.id)}" aria-label="Close comments">${svg('close',18)}</button></header><div class="vc-post-comments-content">${postCommentsMarkup(post)}</div></section>`;}

function postCard(post) {
  const vote = post.vote || (post.voted ? 1 : 0);
  const media = sessionMedia.get(post.id);
  const video = post.type === 'reel' || post.tag === 'Video' || media?.type === 'video';
  const postAuthor = post.autoGenerated
    ? `<span class="vc-author-name">${esc(post.author)} <span>· Source-led</span></span>`
    : post.sample
    ? `<span class="vc-author-name">${esc(post.author)} <span>· Sample</span></span>`
    : `<button data-action="view-member" data-name="${esc(post.author)}">${esc(post.author)} <span>· ${post.anonymous === false ? 'Member' : 'Pseudonym'}</span></button>`;
  return `<article class="vc-post" id="${esc(post.id)}">
    <div class="vc-post-head">${userAvatar({ name: post.author, avatarTone: 'anon' })}<div class="vc-author">${postAuthor}<small><button data-community-slug="${esc(communityData().find(item => item.name === post.community)?.slug || 'womens-health')}">w/${esc(communityData().find(item => item.name === post.community)?.slug || 'womens-health')}</button> · ${esc(post.time || 'Recently')}</small></div><button class="vc-more" data-action="${post.ownerHandle === user().handle ? 'own-post-menu' : 'report-post'}" data-id="${esc(post.id)}" aria-label="Post options">${svg('more', 18)}</button></div>
    ${post.sample ? `<span class="vc-sample-post-label">SAMPLE POST · SOURCE NOT VERIFIED</span>` : ''}
    ${post.autoGenerated ? `<span class="vc-auto-content-label">OFFICIAL SOURCE · ${esc(post.sourceLabel || 'Verified feed')}</span>` : ''}
    ${post.title ? `<h2 class="vc-post-title">${esc(post.title)}</h2>` : ''}<p class="vc-post-copy">${esc(post.body || post.caption || '')}</p>
    ${post.autoGenerated ? `<div class="vc-auto-source"><a href="${/^https:\/\/(?:www\.)?nih\.gov\//i.test(post.sourceUrl || '') ? esc(post.sourceUrl) : 'https://www.nih.gov/news-events/news-releases'}" target="_blank" rel="noopener noreferrer">Read the ${esc(post.sourceLabel || 'official source')} ↗</a><span>${esc(post.sourceNote || 'Read the source for context. Not medical advice.')}</span></div>` : ''}
    ${post.poll ? `<section class="vc-poll"><strong>${esc(post.poll.question)}</strong>${post.poll.options.map((option, index) => `<button class="${post.poll.selected === index ? "selected" : ""}" aria-pressed="${post.poll.selected === index}" data-action="vote-poll" data-id="${esc(post.id)}" data-option="${index}">${esc(option)}<span>${post.poll.votes?.[index] || 0}</span></button>`).join('')}</section>` : ''}
    ${media?.url || post.mediaUrl ? (video ? `<video class="vc-media" src="${esc(media?.url || post.mediaUrl)}" ${post.mediaPoster?`poster="${esc(post.mediaPoster)}"`:''} controls playsinline preload="metadata" aria-label="Video by ${esc(post.author)}"></video>` : `<img class="vc-media" src="${esc(media?.url || post.mediaUrl)}" alt="${esc(post.mediaAlt || 'Post image')}" loading="lazy">`) : samplePostArtwork(post)}
    ${post.tags?.length ? `<div class="vc-hashtags">${post.tags.map(tag => `<button data-search-tag="${esc(tag)}">#${esc(tag)}</button>`).join('')}</div>` : ''}
    <div class="vc-post-actions"><button class="${vote === 1 ? 'is-selected' : ''}" data-action="vote" data-vote="1" data-id="${esc(post.id)}" aria-label="Like post">${svg('heart', 18)}<span>${Number(post.likes ?? Math.max(post.votes || 0, 0))}</span></button><button class="${vote === -1 ? 'is-selected' : ''}" data-action="vote" data-vote="-1" data-id="${esc(post.id)}" aria-label="Dislike post">${svg('down', 17)}</button><button data-action="toggle-comments" data-id="${esc(post.id)}" aria-label="Open comments" aria-expanded="${state.openPostCommentsId===post.id}">${svg('comment', 18)}<span>${postCount(post)}</span></button><button data-action="share-post" data-id="${esc(post.id)}" aria-label="Share post">${svg('send', 17)}</button><button class="vc-save ${post.saved ? 'is-selected' : ''}" data-action="save-post" data-id="${esc(post.id)}" aria-label="Save post">${svg('bookmark', 18)}</button></div>
    ${post.comments?.[0] ? `<button class="vc-comment-peek" data-action="toggle-comments" data-id="${esc(post.id)}" aria-expanded="${state.openPostCommentsId===post.id}">View all ${postCount(post)} replies · <span>${esc(post.comments[0].author)}</span> ${esc(post.comments[0].text)}</button>` : ''}
    ${state.openPostCommentsId===post.id?postCommentsPanel(post):''}
  </article>`;
}

function storyTray() {
  const stories = (state.stories || []).filter(story => sessionMedia.has(`story:${story.id}`) && Date.now() - Number(story.createdAt || 0) < 24 * 60 * 60 * 1000);
  const allStories=[...stories,...sampleStories],accounts=new Map();
  allStories.forEach(story=>{if(!accounts.has(story.author))accounts.set(story.author,[]);accounts.get(story.author).push(story);});
  const circles=[...accounts.values()].map(items=>{const first=items[0],viewed=items.every(item=>item.id.startsWith('sample-story')?(state.viewedSampleStories||[]).includes(item.id):item.viewed),poster=first.poster||'';return `<button class="vc-story" data-action="view-story" data-id="${esc(first.id)}"><span class="vc-story-ring ${viewed?'viewed':''}"><span>${poster?`<img class="vc-story-thumb" src="${esc(poster)}" alt="" loading="lazy">`:esc(first.initials||'VC')}</span></span><span>${esc(first.author)}</span></button>`;}).join('');
  return `<section class="vc-stories" aria-label="Stories"><div class="vc-story-strip"><button class="vc-story" data-action="add-story"><span class="vc-story-ring add"><span>${svg('plus', 18)}</span></span><span>Your story</span></button>${circles}</div></section>`;
}

function homeView() {
  const following = (state.profileFollows || []).filter(item => item.from === user().handle).map(item => item.to);
  let posts = activeSection() === 'home' && state.communityFeedTab === 'following'
    ? state.posts.filter(post => following.includes(post.ownerHandle) || (state.followed || []).includes(post.community) || (state.followedTopics || []).some(topic => `${post.title} ${post.body} ${(post.tags || []).join(" ")}`.toLowerCase().includes(topic.toLowerCase())))
    : [...state.posts];
  if ((state.communityFeedSort || "Latest") === "Top") posts.sort((a,b) => Number(b.votes || b.likes || 0) - Number(a.votes || a.likes || 0));
  return `<div class="vc-content-grid"><main class="vc-main-column"><h1 class="vc-visually-hidden">Community feed</h1>${storyTray()}<div class="vc-composer"><span>${userAvatar()}</span><button class="vc-composer-input" data-action="compose">Share a thought, a moment or a question…</button><button class="vc-composer-add" data-action="compose" aria-label="Create a post">${svg('plus', 19)}</button></div><div class="vc-feed-toolbar"><div class="vc-segment" role="tablist" aria-label="Feed selection"><button role="tab" aria-selected="${!state.communityFeedTab || state.communityFeedTab === 'for-you'}" class="${!state.communityFeedTab || state.communityFeedTab === 'for-you' ? 'active' : ''}" data-feed-tab="for-you">For you</button><button role="tab" aria-selected="${state.communityFeedTab === 'following'}" class="${state.communityFeedTab === 'following' ? 'active' : ''}" data-feed-tab="following">Following</button></div><button class="vc-filter" data-action="feed-sort">${svg('sort', 15)} ${esc(state.communityFeedSort || 'Latest')}</button></div><div class="vc-feed" id="vc-feed">${posts.map(postCard).join('') || `<div class="vc-empty"><span>${svg('spark', 22)}</span><h2>Your feed is finding its rhythm</h2><p>Follow a community or creator to see conversations here.</p><button class="vc-soft-button" data-community-section="communities">Explore communities</button></div>`}</div></main><aside class="vc-side-column"><section class="vc-side-block"><div class="vc-side-title"><div><span>Find your people</span><h2>Communities to explore</h2></div><button data-community-section="communities" aria-label="See all communities">${svg('arrow', 15)}</button></div><div class="vc-mini-communities">${communityData().slice(0, 4).map((item, index) => `<div class="vc-mini-community"><span class="vc-community-icon ${item.color}">${['✳', '◒', '◌', '✧'][index]}</span><div><strong>w/${esc(item.slug)}</strong><small>${memberLabel(item)}</small></div><button data-community-slug="${esc(item.slug)}" aria-label="Open w/${esc(item.slug)}">›</button></div>`).join('')}</div></section><section class="vc-gentle-note"><span class="vc-note-icon">${svg('shield', 16)}</span><div><strong>A thoughtful space</strong><p>Share from your experience. Protect details that identify you.</p></div></section><div class="vc-footer-note">Community is peer support, not medical advice.<br><button data-action="guidelines">Read our guidelines</button></div></aside></div>`;
}

function exploreView() {
  const query = state.communitySearch || '';
  const category = state.exploreCategory || 'For You';
  const normalized = query.trim().toLowerCase();
  const categoryMedia = sampleExploreItems.filter(item => category === 'For You' || item.category === category);
  const matchingMedia = categoryMedia.filter(item => !normalized || `${item.title} ${item.caption} ${item.category} ${item.format}`.toLowerCase().includes(normalized));
  const communityMatches = (category === 'Communities' || category === 'For You') ? communityData().filter(item => !normalized || `${item.name} ${item.description} ${item.slug}`.toLowerCase().includes(normalized)) : [];
  const recent = state.exploreRecentSearches || [];
  const hasSuggestions = Boolean(state.exploreSearchOpen);
  const mediaMarkup = categoryMedia.map(item => exploreMediaCard(item, Boolean(normalized && !matchingMedia.includes(item)))).join('');
  const communityMarkup = communityMatches.map(item => exploreCommunityCard(item, category === 'For You' && !normalized)).join('');
  const noContent = category === 'Doctors'
    ? 'Verified provider profiles are not connected in this preview.'
    : category === 'Research'
      ? 'Reviewed research sources are not connected in this preview. Browse community media separately from published evidence.'
      : category === 'Communities'
        ? 'No communities match this search.'
        : 'Try another category or search term.';
  const resultCount = category === 'Communities' ? communityMatches.length : matchingMedia.length + (normalized ? communityMatches.length : 0);
  const emptyTitle = normalized ? `No results for “${esc(query)}”` : `${esc(category)} is quiet for now`;
  const emptyMarkup = `<div class="vc-explore-empty" id="vc-explore-empty" ${resultCount ? 'hidden' : ''}><span>${svg(category === 'Research' ? 'book' : 'search', 20)}</span><strong id="vc-explore-empty-title">${emptyTitle}</strong><p>${esc(noContent)}</p><button data-action="explore-clear-search" ${normalized ? '' : 'hidden'}>Clear search</button></div>`;
  const searchTerms = [...new Set([...recent,'Women’s health','PCOS','Mental Wellness','Nutrition','Communities',...exploreCategories,...sampleExploreItems.map(item=>item.title),...communityData().map(item=>item.name)])];
  return `<section class="vc-explore-page"><header class="vc-explore-hero"><div class="vc-explore-search-wrap"><label class="vc-explore-search">${svg('search', 20)}<input id="vc-search" type="search" placeholder="Search ideas, stories and communities" value="${esc(query)}" aria-label="Search ideas, stories and communities" autocomplete="off"><button type="button" class="vc-search-clear" data-action="explore-clear-search" aria-label="Clear search" ${query ? '' : 'hidden'}>${svg('close', 16)}</button></label><div class="vc-search-suggestions" ${hasSuggestions ? '' : 'hidden'}><span>${normalized ? 'SUGGESTED SEARCHES' : recent.length ? 'RECENT SEARCHES' : 'POPULAR SEARCHES'}</span>${searchTerms.map(item => `<button type="button" data-explore-suggest="${esc(item)}" ${normalized && !item.toLowerCase().includes(normalized) ? 'hidden' : ''}>${svg('search', 14)}${esc(item)}<span>↗</span></button>`).join('') || `<small>Keep typing to search sample posts and communities.</small>`}</div></div></header><nav class="vc-explore-categories" aria-label="Explore categories">${exploreCategories.map(item => `<button class="${category === item ? 'active' : ''}" aria-pressed="${category === item}" data-explore-category="${esc(item)}">${esc(item)}</button>`).join('')}</nav><div class="vc-masonry" id="vc-explore-feed">${mediaMarkup}${communityMarkup}${emptyMarkup}</div></section>`;
}

function exploreMediaCard(item, hidden = false) {
  const src = sampleMediaUrl(item.media);
  const posterSrc = item.poster ? samplePosterUrl(item.poster) : '';
  const media = item.kind === 'video'
    ? `<button type="button" class="vc-explore-image-open" data-action="open-explore-item" data-id="${esc(item.id)}" aria-label="Open video ${esc(item.title)}"><video class="vc-explore-media" data-explore-video src="${esc(src)}" ${posterSrc?`poster="${esc(posterSrc)}"`:''} muted loop playsinline preload="metadata" aria-label="${esc(item.alt)}"></video></button>`
    : `<button type="button" class="vc-explore-image-open" data-action="open-explore-item" data-id="${esc(item.id)}" aria-label="Open ${esc(item.title)}"><img class="vc-explore-media" src="${src}" alt="${esc(item.alt)}" loading="lazy"></button>`;
  const searchText = `${item.title} ${item.caption} ${item.category} ${item.format}`.toLowerCase();
  return `<article class="vc-discovery-card ${item.kind === 'video' ? 'is-video' : ''}" id="${esc(item.id)}" data-explore-result data-search-text="${esc(searchText)}" ${hidden ? 'hidden' : ''}><div class="vc-discovery-media-wrap">${media}</div><div class="vc-discovery-copy"><button type="button" class="vc-discovery-title" data-action="open-explore-item" data-id="${esc(item.id)}">${esc(item.title)}</button><p>${esc(item.caption)}</p></div></article>`;
}
function exploreCommunityCard(item, hidden = false) {
  const joined = (state.followed || []).includes(item.name);
  const searchText = `${item.name} ${item.description} ${item.slug}`.toLowerCase();
  return `<article class="vc-discovery-community" data-explore-result data-search-text="${esc(searchText)}" ${hidden ? 'hidden' : ''}><span class="vc-community-icon ${item.color}">${svg('heart', 17)}</span><span class="vc-eyebrow">COMMUNITY</span><button type="button" class="vc-discovery-community-title" data-community-slug="${esc(item.slug)}" aria-label="Open w/${esc(item.slug)}">w/${esc(item.slug)}</button><p>${esc(item.description)}</p><small>${memberLabel(item)}</small><button class="${joined ? 'joined' : ''}" data-action="follow" data-community="${esc(item.name)}">${joined ? 'Joined' : 'Join community'}</button></article>`;
}

function reelsView() {
  const reels = state.posts.filter(post => (post.type === 'reel' || post.tag === 'Video') && (post.autoReel || post.mediaUrl || sessionMedia.get(post.id)?.url));
  return `<section class="vc-reels-page"><header class="vc-reels-header"><button class="vc-soft-button" data-action="compose-video" aria-label="Share a reel">${svg('plus',16)}</button></header>${reels.length ? `<div class="vc-reel-feed" aria-label="Reels feed">${reels.map((post,index)=>{
    const media=sessionMedia.get(post.id), src=media?.url||post.mediaUrl;
    const liked=post.voted===true||post.vote===1;
    const caption=String(post.body||post.title||'A moment shared with the community.').trim();
    const generated=Boolean(post.autoReel);
    const shortCaption=caption.length>72?`${caption.slice(0,69).trimEnd()}…`:caption;
    const slide=generated?`<div class="vc-auto-reel-art" aria-label="Animated research source card"><span class="vc-auto-reel-orbit" aria-hidden="true"></span><span class="vc-auto-reel-kicker">A RESEARCH NOTE · NIH</span><strong>${esc(post.title)}</strong><p>${esc(post.autoReel.summary||caption)}</p><a href="${/^https:\/\/(?:www\.)?nih\.gov\//i.test(post.autoReel.sourceUrl||'')?esc(post.autoReel.sourceUrl):'https://www.nih.gov/news-events/news-releases'}" target="_blank" rel="noopener noreferrer">Read the source ${svg('arrow',14)}</a><small>Source-led summary · Not medical advice</small></div>`:`<video data-reel-video src="${esc(src)}" controls playsinline ${reelSoundEnabled?'':'muted'} preload="metadata" aria-label="Video by ${esc(post.author)}"></video>`;
    return `<article class="vc-reel-card ${generated?'is-auto-reel':''}" data-reel-card data-reel-id="${esc(post.id)}"><div class="vc-reel-media">${slide}${generated?'':`<div class="vc-reel-caption"><div class="vc-reel-author">${userAvatar({name:post.author})}<strong>${esc(post.author)}</strong><button data-action="toggle-member-follow" data-name="${esc(post.author)}" data-handle="${esc(post.ownerHandle||post.author)}">Follow</button></div>${caption.length>72?`<button class="vc-reel-caption-text" data-action="toggle-reel-caption" data-caption-short="${esc(shortCaption)}" data-caption-full="${esc(caption)}" aria-expanded="false">${esc(shortCaption)}</button>`:`<p class="vc-reel-caption-text">${esc(caption)}</p>`}<small>${esc(post.community||'Vericove community')} · ${index+1} of ${reels.length}</small></div>`}</div><div class="vc-reel-rail">${generated?'':`<button class="vc-reel-sound" data-action="toggle-reel-sound" aria-label="${reelSoundEnabled?'Mute':'Enable'} reel sound">${svg(reelSoundEnabled?'volume':'volumeOff',22)}<span>${reelSoundEnabled?'Sound on':'Sound'}</span></button>`}<button class="${liked?'is-liked':''}" data-action="vote" data-vote="1" data-id="${esc(post.id)}" aria-label="${liked?'Unlike':'Like'} reel" aria-pressed="${liked}">${svg('heart',23)}<span>${Number(post.likes??post.votes??0)}</span></button><button data-action="toggle-comments" data-id="${esc(post.id)}" aria-label="Read ${postCount(post)} comments">${svg('comment',23)}<span>${postCount(post)}</span></button><button data-action="share-post" data-id="${esc(post.id)}" aria-label="Share reel">${svg('send',22)}<span>Share</span></button><button data-action="save-post" data-id="${esc(post.id)}" aria-label="Save reel">${svg('bookmark',21)}<span>Save</span></button><button data-action="reel-more" data-id="${esc(post.id)}" aria-label="More reel options">${svg('more',21)}</button></div><div class="vc-reel-pager"><button data-action="reel-prev" aria-label="Previous reel">${svg('arrow',22)}</button><button data-action="reel-next" aria-label="Next reel">${svg('arrow',22)}</button></div></article>`;
  }).join('')}</div>` : `<div class="vc-empty vc-reels-empty"><span>${svg('file',24)}</span><h2>Stories are better in motion</h2><p>Share a short video with a community.</p><button class="vc-primary-button" data-action="compose-video">Create your first reel</button></div>`}<p class="vc-reels-note">Auto reels are animated source cards. Read the official release for full context.</p></section>`;
}
function communitiesView() {
  const selected = state.selectedCommunitySlug;
  const catalog = communityData();
  const active = catalog.find(item => item.slug === selected);
  if (active) {
    const joined = (state.followed || []).includes(active.name);
    const posts = state.posts.filter(post => post.community === active.name);
    if ((state.communitySort || 'Helpful') === 'Recent') posts.sort((a,b) => String(b.id).localeCompare(String(a.id)));
    else posts.sort((a,b) => Number(b.votes || b.likes || 0) - Number(a.votes || a.likes || 0));
  return `<section class="vc-community-detail"><button class="vc-back-link" data-community-section="communities">${svg('arrow', 14)} All communities</button><div class="vc-community-banner ${active.color}" style="background-image:linear-gradient(90deg,rgba(42,32,46,.25),rgba(42,32,46,.02)),url('${esc(active.cover)}')"><span class="vc-community-icon large">✳</span><span class="vc-community-prefix">w/${esc(active.slug)}</span></div><div class="vc-community-heading"><div><span class="vc-eyebrow">A Vericove community</span><h1>w/${esc(active.slug)}</h1><p>${esc(active.description)}</p><span class="vc-member-count">${memberLabel(active)} · Open community</span></div><div class="vc-community-cta"><button class="${joined ? 'vc-soft-button' : 'vc-primary-button'}" data-action="follow" data-community="${esc(active.name)}">${joined ? 'Joined' : 'Join community'}</button><button class="vc-soft-button" data-action="compose" data-community-name="${esc(active.name)}">Create post</button></div></div><div class="vc-community-rules"><strong>Community care</strong><span>Lead with lived experience. Keep advice kind, sourced and clearly personal.</span><button data-action="guidelines">Read rules</button></div><div class="vc-feed-toolbar"><div class="vc-segment"><button class="${!state.communitySort || state.communitySort === 'Helpful' ? 'active' : ''}" data-community-sort="Helpful">Top</button><button class="${state.communitySort === 'Recent' ? 'active' : ''}" data-community-sort="Recent">New</button><button class="${state.communitySort === 'Hot' ? 'active' : ''}" data-community-sort="Hot">Hot</button></div></div><div id="discussion-list" class="vc-feed">${posts.map(postCard).join('') || `<div class="vc-empty"><h2>Start the conversation</h2><p>Share a question or experience with this community.</p><button class="vc-primary-button" data-action="compose" data-community-name="${esc(active.name)}">Create the first post</button></div>`}</div></section>`;
  }
  return `<section class="vc-communities-page"><h1 class="vc-visually-hidden">Communities</h1><header class="vc-communities-search"><label class="vc-explore-search">${svg('search', 18)}<input id="vc-community-search" type="search" placeholder="Find a community" aria-label="Search communities"><kbd>⌘ K</kbd></label></header><div class="vc-community-grid">${catalog.map((item, index) => `<article class="vc-community-tile"><button class="vc-community-open" data-community-slug="${esc(item.slug)}"><div class="vc-community-cover ${item.color}" style="background-image:linear-gradient(180deg,rgba(35,28,38,.04),rgba(35,28,38,.2)),url('${esc(item.cover)}')"><span class="vc-community-icon large">${['✳', '◒', '◌', '✧'][index % 4]}</span><span class="vc-community-prefix">w/${esc(item.slug)}</span></div><div class="vc-community-tile-copy"><span class="vc-eyebrow">Community space</span><h2>${esc(item.name)}</h2><p>${esc(item.description)}</p><span class="vc-member-count">${memberLabel(item)}</span></div></button><button class="${(state.followed || []).includes(item.name) ? 'vc-soft-button' : 'vc-primary-button'} vc-join-button" data-action="follow" data-community="${esc(item.name)}">${(state.followed || []).includes(item.name) ? 'Joined' : 'Join'}</button></article>`).join('')}</div></section>`;
}

